import{z as l,x as d,o as s,c as B,q as t,j as i,D as r,d as E,s as n,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Windows Kerberos 攻击","description":"","frontmatter":{"title":"Windows Kerberos 攻击","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/windows-kerberos-attacks.md","filePath":"cs/windows-kerberos-attacks.md","lastUpdated":1791413859000}'),T={name:"cs/windows-kerberos-attacks.md"};function p(D,a,C,b,c,h){const o=d("Mermaid");return s(),B("div",null,[a[2]||(a[2]=t('<h1 id="windows-kerberos-攻击" tabindex="-1">Windows Kerberos 攻击 <a class="header-anchor" href="#windows-kerberos-攻击" aria-label="Permalink to &quot;Windows Kerberos 攻击&quot;">​</a></h1><div class="epigraph"><p>Kerberos 把票据当能力。票据太强、哈希可离线、委派过宽时，域内横向变成协议合同问题。防御是限制委派、保护 KRBTGT、短寿命，而不是默记攻击商品名。</p><footer>—— 据 RFC 4120；Bellovin and Merritt 对 Kerberos 的早期讨论；Microsoft 对委派与 PAC 的文档；对照主干[Kerberos](/cs/kerberos)</footer></div><p>上一课<a href="/cs/linux-privesc">Linux 提权</a>停在单机。本课补<strong>域身份</strong>这一缺口：主干 <a href="/cs/kerberos">Kerberos</a> 已给过 TGT 直觉，这里收 Windows 域里常见的合同失败——票据太强、哈希可离线、委派过宽（黄金票据一类只作机制点名），不给可复制的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TGT 与服务票一旦被盗，两扇窗同时打开：服务票的加密块可被离线爆破，服务账户口令弱时数小时内即得密钥；票据寿命之内可以重放。无约束委派更糟——被委派的服务能拿到用户的可转发票据，转身冒充该用户访问任意后端。缺口因此是三件事：保护域控、限制委派、监控异常 TGT（寿命、请求模式、加密类型）。</p><h3 id="哈希不等于口令" tabindex="-1">哈希不等于口令 <a class="header-anchor" href="#哈希不等于口令" aria-label="Permalink to &quot;哈希不等于口令&quot;">​</a></h3><p>Kerberos 的长期凭据是密钥材料而非口令本身：NT 哈希与口令等价。长期密钥材料一旦泄漏即可离线自签票据，口令策略再严也拦不住已拿走密钥的人——能拦的是轮换与短寿命。</p><p><span class="marginnote">直觉类比：NT 哈希像你家门锁的钥匙坯——服务器不记「你设了什么口令」，只存钥匙本身的形状；谁复制了钥匙坯，改口令策略都没用，唯一的解是换锁（轮换密钥）。</span></p><p><span class="marginnote">RFC 4120。课程禁止 Kerberos 攻击操作指导。只讲：票据是能力，能力过宽则横向。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 Linux 的 sudo：单机把能力收敛在 sudoers 规则里，域里则收敛在委派配置与 PAC 上。硬化对应缺口三件套：委派改约束式，限定目标服务与协议；敏感账户进受保护用户组，拒绝降级加密；KRBTGT 建立两轮轮换流程，使旧票全部失效要覆盖一个最大票据寿命。下一课 TEE。</p>',12)),(s(),i(A,null,{default:r(()=>[n(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TGT%5B%22TGT%20%E8%83%BD%E5%8A%9B%22%5D%20--%3E%20SVC%5B%22%E6%9C%8D%E5%8A%A1%E7%A5%A8%22%5D%0A%20%20DEL%5B%22%E8%BF%87%E5%AE%BD%E5%A7%94%E6%B4%BE%22%5D%20--%3E%20IMP%5B%22%E5%86%92%E5%85%85%E7%94%A8%E6%88%B7%22%5D%0A%20%20HARD%5B%22%E7%BA%A6%E6%9D%9F%E5%A7%94%E6%B4%BE%E4%B8%8E%E7%9F%AD%E5%AF%BF%E5%91%BD%22%5D%20--%3E%20LIM%5B%22%E7%BC%A9%E5%B0%8F%E8%83%BD%E5%8A%9B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"机制上的根源是「身份完全在票据里」：验证方只认票不认人，票即能力，谁持有谁就是那个身份。合同的关键参数因此是寿命与范围——短寿命压缩重放窗口，约束委派划定能力边界；二者任一失守，横向只剩检测可用。HSM/TEE 下一课把密钥再往硬件里塞。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：无约束委派就是「把整张通行证借给前台代办」——前台能拿它去任何后端；约束委派换成「只准代办指定一间房、办指定一件事」的限用单据，能力边界被写死。")],-1)),(s(),i(A,null,{default:r(()=>[n(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20K1%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E6%8C%81%E6%97%A7%20KRBTGT%20%E5%AF%86%E9%92%A5%E4%BC%AA%E9%80%A0%20TGT%22%5D%20--%3E%20R1%5B%22%E7%AC%AC%E4%B8%80%E6%AC%A1%E8%BD%AE%E6%8D%A2%20KRBTGT%22%5D%0A%20%20R1%20--%3E%20V%7B%22DC%20%E7%94%A8%E6%96%B0%E5%AF%86%E9%92%A5%E9%AA%8C%E7%A5%A8%22%7D%0A%20%20V%20--%3E%7C%22%E6%97%A7%E5%AF%86%E9%92%A5%E4%BC%AA%E9%80%A0%E7%9A%84%20TGT%22%7C%20FAIL%5B%22%E9%AA%8C%E7%AD%BE%E5%A4%B1%E8%B4%A5%EF%BC%8C%E9%87%91%E7%A5%A8%E5%A4%B1%E6%95%88%22%5D%0A%20%20R1%20--%3E%20R2%5B%22%E7%AC%AC%E4%BA%8C%E6%AC%A1%E8%BD%AE%E6%8D%A2%EF%BC%8C%E8%A6%86%E7%9B%96%E5%90%84%20DC%20%E7%BC%93%E5%AD%98%22%5D%0A%20%20R2%20--%3E%20OK%5B%22%E5%9F%9F%E6%81%A2%E5%A4%8D%E6%AD%A3%E5%B8%B8%E7%AD%BE%E5%8F%91%EF%BC%8C%E4%B8%8D%E7%95%99%E6%97%A7%E9%92%A5%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写任何造票与导出步骤；黄金票据只作为「KRBTGT 长期不轮换」的失败模式被点名。TEE（SGX/TrustZone）下一课。</p><p><span class="marginnote">为什么重要：KRBTGT 是域内所有 TGT 的签发密钥，泄漏等于身份证打印机被偷；只轮换一次不够——旧密钥可能还留在备份 DC 缓存里，标准做法是两轮轮换并覆盖一个最大票据寿命，才能确认伪造票全部过期。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单机提权之外，域票据本身就是横向能力。</li><li>委派宽度与 KRBTGT 轮换是合同的核心参数。</li><li>只点名失败模式，不给操作链。</li><li>下一课 TEE。</li><li>出处：RFC 4120；Bellovin and Merritt；Microsoft 委派文档；<a href="/cs/kerberos">kerberos</a>。</li></ul>',5))])}const f=l(T,[["render",p]]);export{u as __pageData,f as default};
